<?php declare(strict_types=1);use FastWebsite\Core\View;?>
<section class="page-heading department-heading"><div class="shell"><p class="eyebrow"><?=View::escape(View::setting($siteContent??[],'engagement.eyebrow','Working together'))?></p><h1><?=View::escape(View::setting($siteContent??[],'engagement.title','Partnerships and impact'))?></h1><p class="lead"><?=View::escape(View::setting($siteContent??[],'engagement.introduction','See how FAST collaborates and turns knowledge into public value.'))?></p></div></section><section class="section"><div class="shell"><h2>Partnerships</h2><?php if($partnerships===[]):?><div class="public-empty"><p>Published formal partnerships will appear here.</p></div><?php else:?><div class="feature-grid"><?php foreach($partnerships as$p):?><article><p class="eyebrow"><?=View::escape(ucwords(str_replace('_',' ',$p['partnership_type'])))?></p><h3><?=View::escape($p['title'])?></h3><p><strong><?=View::escape($p['partner_name'])?></strong></p><p><?=View::escape($p['description']??'')?></p></article><?php endforeach;?></div><?php endif;?></div></section><section class="section research-metadata-section"><div class="shell"><h2>Impact stories</h2><?php if($impacts===[]):?><div class="public-empty"><p>Published impact stories will appear here.</p></div><?php else:?><div class="department-card-grid"><?php foreach($impacts as$i):?><article class="department-card"><div><p class="eyebrow"><?=View::escape($i['impact_date']??'Impact')?></p><h3><a href="<?=View::escape($baseUrl)?>impact/<?=View::escape($i['slug'])?>"><?=View::escape($i['title'])?></a></h3><p><?=View::escape($i['summary']??'')?></p></div></article><?php endforeach;?></div><?php endif;?></div></section>
